/* GENERATED by _tools/emit_web.py - do not edit. Test 9, Part 1. */
IELTS.lesson({"test": 9, "part": 1, "title": "Test 9, Part 1 — the interview", "candidate": "samir", "script": [{"who": "examiner", "text": "Good morning. Come in, have a seat.", "ar": "صباح الخير. تفضّل بالدخول واجلس.", "shot": "two", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/1b2def3fa2b0b362.mp3"}, {"who": "examiner", "text": "My name is Mohamad Khorbatli. Can you tell me your full name, please?", "ar": "اسمي محمد خرباطلي. هل يمكنك أن تخبرني باسمك الكامل من فضلك؟", "shot": "two", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/c756d0707f344069.mp3"}, {"who": "candidate", "text": "Samir Othman.", "ar": "سمير عثمان.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-joe-medium-s119", "clip": "../clips/c66347006ccee4f3.mp3"}, {"who": "examiner", "text": "And what can I call you?", "ar": "وبماذا أناديك؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/5085ae49113e09cf.mp3"}, {"who": "candidate", "text": "Samir is fine.", "ar": "سمير تكفي.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-joe-medium-s119", "clip": "../clips/a46cccf93a61f0e1.mp3"}, {"who": "examiner", "text": "Thank you, Samir. Can I see your identification, please?", "ar": "شكراً لك يا سمير. هل يمكنني رؤية هويّتك من فضلك؟", "shot": "two", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/959a5972e556f391.mp3"}, {"who": "candidate", "text": "Of course. Here you are.", "ar": "بالتأكيد. تفضّل.", "shot": null, "sex": "m", "voice": "piper-en_US-joe-medium-s119", "clip": "../clips/b398597e85e8fd36.mp3"}, {"who": "examiner", "text": "Thank you. That's all fine.", "ar": "شكراً. كل شيء على ما يرام.", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/a65ff8d3eccec277.mp3"}, {"who": "examiner", "text": "Now, in this first part I'd like to ask you some questions about yourself. Let's talk about news and reading.", "ar": "الآن، في هذا الجزء الأول أودّ أن أطرح عليك بعض الأسئلة عنك. لنتحدّث عن الأخبار والقراءة.", "shot": "two", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/ab9227db2e85bdd7.mp3"}, {"who": "examiner", "text": "How do you usually follow the news?", "ar": "كيف تتابع الأخبار عادةً؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/79a807168521f17a.mp3"}, {"who": "candidate", "text": "Badly, and deliberately so. I read one long thing at the weekend and I've given up on the daily version entirely. You see, I found I was better informed and worse at thinking, which seemed a poor trade. That's what thirty years in a Damascus classroom does to you.", "ar": "بشكل سيّئ، وعن قصد. أقرأ مادّة واحدة طويلة في نهاية الأسبوع وتخلّيت تماماً عن المتابعة اليوميّة. انظر، وجدت أنّني صرت أعرف أكثر وأفكّر أسوأ، وبدت لي تلك صفقة خاسرة. هذا ما تفعله بك ثلاثون سنة في صفّ في دمشق.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-joe-medium-s119", "clip": "../clips/2af790a3f47b6dc5.mp3"}, {"who": "examiner", "text": "Do you read newspapers?", "ar": "هل تقرأ الصحف؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/d448fe82d0618538.mp3"}, {"who": "candidate", "text": "On paper, no, not for years. I miss the shape of it, though. A paper had edges, you finished it. Nothing finishes now.", "ar": "على الورق، لا، منذ سنوات. لكنّني أفتقد شكلها. الصحيفة كانت لها حدود، تنهيها. لا شيء ينتهي الآن.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-joe-medium-s119", "clip": "../clips/d8f4494f7eb2f8fb.mp3"}, {"who": "examiner", "text": "Do you prefer reading books or watching television?", "ar": "هل تفضّل قراءة الكتب أم مشاهدة التلفاز؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/f6f8a168e818e230.mp3"}, {"who": "candidate", "text": "Books, overwhelmingly, and honestly I'd better admit that's partly showing off. I teach in Damascus and I'm supposed to say that. But the honest reason is slower: a book waits for you and a programme doesn't.", "ar": "الكتب، وبفارق كبير، وبصراحة يستحسن أن أعترف أنّ في ذلك شيئاً من التباهي. أنا أعلّم في دمشق ومن المفترض أن أقول ذلك. لكنّ السبب الصادق أبطأ: الكتاب ينتظرك والبرنامج لا ينتظر.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-joe-medium-s119", "clip": "../clips/4dd29846df5bca00.mp3"}, {"who": "examiner", "text": "What kind of books do you enjoy?", "ar": "أيّ نوع من الكتب تستمتع به؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/18565be1a0177e2e.mp3"}, {"who": "candidate", "text": "Poetry, mostly, which makes me insufferable at parties in Damascus. And I reread more than I read. I've probably got forty books I've been through four times and a hundred I've never opened.", "ar": "الشعر في معظمه، وهذا يجعلني ثقيلاً في السهرات في دمشق. وأعيد القراءة أكثر مما أقرأ. عندي على الأرجح أربعون كتاباً مررت بها أربع مرّات ومئة لم أفتحها قطّ.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-joe-medium-s119", "clip": "../clips/6733e4acc30bfe55.mp3"}, {"who": "examiner", "text": "Let's move on to talk about films.", "ar": "لننتقل للحديث عن الأفلام.", "shot": "two", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/aaf61e066474fdd3.mp3"}, {"who": "examiner", "text": "Do you watch many films?", "ar": "هل تشاهد أفلاماً كثيرة؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/582cec8f31e3b16c.mp3"}, {"who": "candidate", "text": "Not many, no. My daughters watch a great deal and I usually end up in the room, because our building is small. So I've seen a lot of films the way you've been to a place you were driven through.", "ar": "ليست كثيرة، لا. ابنتاي تشاهدان كثيراً وأنتهي عادةً إلى الجلوس في الغرفة، لأنّ مبنانا صغير. فقد رأيت أفلاماً كثيرة بالطريقة التي زرت فيها مكاناً مررت به في سيّارة.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-joe-medium-s119", "clip": "../clips/484c6ce8152fb6f4.mp3"}, {"who": "examiner", "text": "What kind of films do you like?", "ar": "أيّ نوع من الأفلام تحبّ؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/015d9db038384197.mp3"}, {"who": "candidate", "text": "The slow ones, I suppose. The ones where, although I don't know the proper words for this, I'm afraid, because I teach books in Damascus and not films. The kind where very little happens and you watch people's faces.", "ar": "البطيئة، على ما أظنّ. تلك التي، مع أنّني لا أعرف المصطلحات الصحيحة لهذا، للأسف، لأنّني أعلّم الكتب في دمشق لا الأفلام. النوع الذي يحدث فيه القليل جداً وتراقب فيه وجوه الناس.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-joe-medium-s119", "clip": "../clips/93816c2f6d26cb5e.mp3"}, {"who": "examiner", "text": "Do you prefer watching films at home or at the cinema?", "ar": "هل تفضّل مشاهدة الأفلام في البيت أم في السينما؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/c8d7801b2d761986.mp3"}, {"who": "candidate", "text": "At home, now, I suppose, though that's circumstances and not choice. The cinema has an attention you can't get on a sofa, everybody facing one way in the dark. That's quite a hard thing to arrange in Damascus and we've stopped trying.", "ar": "في البيت، الآن، على ما أظنّ، مع أنّ ذلك ظروف لا اختيار. في السينما انتباه لا تحصل عليه على أريكة، الجميع متّجهون في اتّجاه واحد في العتمة. وهذا أمر صعب ترتيبه في دمشق وقد كففنا عن المحاولة.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-joe-medium-s119", "clip": "../clips/cd874dd42ba930af.mp3"}, {"who": "examiner", "text": "Are films a good way to learn about other countries?", "ar": "هل الأفلام وسيلة جيّدة للتعرّف على بلدان أخرى؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/083e6b9b0d4f1d82.mp3"}, {"who": "candidate", "text": "They're a good way to learn what a country wants to be seen as, which isn't the same thing and is possibly more interesting. Having said that, I've learned more about English life from one television series than from twenty years of teaching its books in Damascus, so I should be careful.", "ar": "هي وسيلة جيّدة لتعرف كيف يريد بلد أن يُرى، وهذا ليس الشيء نفسه وربّما كان أكثر إثارة للاهتمام. ومع ذلك، تعلّمت عن الحياة الإنكليزيّة من مسلسل واحد أكثر مما تعلّمت من عشرين سنة من تعليم كتبها في دمشق، فينبغي أن أكون حذراً.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-joe-medium-s119", "clip": "../clips/55c7ca31ef13feb6.mp3"}, {"who": "examiner", "text": "Finally in this part, let's talk about mornings.", "ar": "وأخيراً في هذا الجزء، لنتحدّث عن الصباح.", "shot": "two", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/548d73dfa1d50d31.mp3"}, {"who": "examiner", "text": "Are you a morning person?", "ar": "هل أنت من أهل الصباح؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/d2a38a97d3afb9e5.mp3"}, {"who": "candidate", "text": "I've become one, which I'm told happens to everybody and I didn't enjoy being told. For about twenty years I did my marking at night, well, after the school in Damascus closed. Now I do it at five, and it's better work, which is annoying.", "ar": "صرت كذلك، ويقولون لي إنّ هذا يحدث للجميع ولم يعجبني أن يقال لي ذلك. لنحو عشرين سنة كنت أصحّح في الليل، حسناً، بعد أن تغلق المدرسة في دمشق. الآن أصحّح في الخامسة، والعمل أفضل، وهذا مزعج.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-joe-medium-s119", "clip": "../clips/b26665987e09a95d.mp3"}, {"who": "examiner", "text": "What do you usually do first in the morning?", "ar": "ما أوّل شيء تفعله في الصباح عادةً؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/e40fce4f14ab12de.mp3"}, {"who": "candidate", "text": "Coffee, and about twenty minutes of doing nothing at all, which my wife thinks is a waste and which is, I think, the only genuinely free part of my day. There isn't another one that's mine in Damascus.", "ar": "قهوة، ونحو عشرين دقيقة لا أفعل فيها شيئاً إطلاقاً، وزوجتي ترى في ذلك إضاعة للوقت، وهو في رأيي الجزء الحرّ الوحيد فعلاً من يومي. ليس هناك جزء آخر يخصّني في دمشق.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-joe-medium-s119", "clip": "../clips/2860ca0eaa880d8b.mp3"}, {"who": "examiner", "text": "Do you think breakfast is an important meal?", "ar": "هل تظنّ أنّ الفطور وجبة مهمّة؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/f30edf788732b9ea.mp3"}, {"who": "candidate", "text": "Important is doing some work in that question. It's the meal I'd miss most, which isn't the same as needing it. You see, I'm quite capable of teaching all morning in Damascus without it and completely incapable of enjoying the morning.", "ar": "كلمة مهمّ تحمل الكثير في هذا السؤال. إنّها الوجبة التي سأفتقدها أكثر من غيرها، وهذا ليس نفسه أن أحتاجها. انظر، أنا قادر تماماً على التعليم طوال الصباح في دمشق بدونها، وعاجز تماماً عن الاستمتاع بالصباح.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-joe-medium-s119", "clip": "../clips/6d58544a953263ab.mp3"}, {"who": "examiner", "text": "Do children in your country start school early?", "ar": "هل يبدأ الأطفال في بلدك المدرسة مبكّراً؟", "shot": "examiner", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/7d089a5be13c5b7a.mp3"}, {"who": "candidate", "text": "Early enough that nobody has had breakfast properly, which every teacher in Damascus will tell you and nothing is done about. I've taught the first lesson of the day for thirty years, and honestly it isn't the lesson anyone learns anything in.", "ar": "مبكّراً بما يكفي ألّا يكون أحد قد تناول فطوره كما يجب، وهذا سيقوله لك كلّ معلّم في دمشق ولا يُفعل شيء حياله. درّست الحصّة الأولى من اليوم ثلاثين سنة، وبصراحة ليست هي الحصّة التي يتعلّم فيها أحد شيئاً.", "shot": "candidate", "sex": "m", "voice": "piper-en_US-joe-medium-s119", "clip": "../clips/4012a0d9eb931c10.mp3"}, {"who": "examiner", "text": "Thank you. That is the end of Part One.", "ar": "شكراً لك. بهذا ينتهي القسم الأول.", "shot": "two", "sex": "m", "voice": "piper-en_GB-alan-medium-s119", "clip": "../clips/50f379466faf1658.mp3"}], "boxes": [{"q": "How do you usually follow the news?", "ar": null, "topic": "News and reading", "model": "Badly, and deliberately so. I read one long thing at the weekend and I've given up on the daily version entirely. You see, I found I was better informed and worse at thinking, which seemed a poor trade. That's what thirty years in a Damascus classroom does to you.", "modelBand": 7.5, "why": "Answers with a judgement on himself, then supplies the trade-off that explains it."}, {"q": "Do you read newspapers?", "ar": null, "topic": "News and reading", "model": "On paper, no, not for years. I miss the shape of it, though. A paper had edges, you finished it. Nothing finishes now.", "modelBand": 7.5, "why": "Three short sentences, the last of them the point. 'Nothing finishes now' is the whole answer."}, {"q": "Do you prefer reading books or watching television?", "ar": null, "topic": "News and reading", "model": "Books, overwhelmingly, and honestly I'd better admit that's partly showing off. I teach in Damascus and I'm supposed to say that. But the honest reason is slower: a book waits for you and a programme doesn't.", "modelBand": 7.5, "why": "Admits the professional motive before giving the real one, which makes the real one believable."}, {"q": "What kind of books do you enjoy?", "ar": null, "topic": "News and reading", "model": "Poetry, mostly, which makes me insufferable at parties in Damascus. And I reread more than I read. I've probably got forty books I've been through four times and a hundred I've never opened.", "modelBand": 7.5, "why": "Self-deprecating, then precise: forty against a hundred is the kind of number a real reader knows about themselves."}, {"q": "Do you watch many films?", "ar": null, "topic": "Films", "model": "Not many, no. My daughters watch a great deal and I usually end up in the room, because our building is small. So I've seen a lot of films the way you've been to a place you were driven through.", "modelBand": 7.5, "why": "Says no and then qualifies it accurately. The driven-through comparison does the work without being decorative."}, {"q": "What kind of films do you like?", "ar": null, "topic": "Films", "model": "The slow ones, I suppose. The ones where, although I don't know the proper words for this, I'm afraid, because I teach books in Damascus and not films. The kind where very little happens and you watch people's faces.", "modelBand": 7.5, "why": "Hesitates, flags the limits of his own vocabulary, and still describes the thing exactly."}, {"q": "Do you prefer watching films at home or at the cinema?", "ar": null, "topic": "Films", "model": "At home, now, I suppose, though that's circumstances and not choice. The cinema has an attention you can't get on a sofa, everybody facing one way in the dark. That's quite a hard thing to arrange in Damascus and we've stopped trying.", "modelBand": 7.5, "why": "Separates what he does from what he prefers, and names what the cinema actually supplies."}, {"q": "Are films a good way to learn about other countries?", "ar": null, "topic": "Films", "model": "They're a good way to learn what a country wants to be seen as, which isn't the same thing and is possibly more interesting. Having said that, I've learned more about English life from one television series than from twenty years of teaching its books in Damascus, so I should be careful.", "modelBand": 7.5, "why": "Makes a distinction, then undercuts his own authority with evidence against himself."}, {"q": "Are you a morning person?", "ar": null, "topic": "Mornings", "model": "I've become one, which I'm told happens to everybody and I didn't enjoy being told. For about twenty years I did my marking at night, well, after the school in Damascus closed. Now I do it at five, and it's better work, which is annoying.", "modelBand": 7.5, "why": "A change he resisted, with the hours on both sides of it and a verdict he dislikes."}, {"q": "What do you usually do first in the morning?", "ar": null, "topic": "Mornings", "model": "Coffee, and about twenty minutes of doing nothing at all, which my wife thinks is a waste and which is, I think, the only genuinely free part of my day. There isn't another one that's mine in Damascus.", "modelBand": 7.5, "why": "Two things, one of them nothing, and a defence of the nothing that does not call itself a defence."}, {"q": "Do you think breakfast is an important meal?", "ar": null, "topic": "Mornings", "model": "Important is doing some work in that question. It's the meal I'd miss most, which isn't the same as needing it. You see, I'm quite capable of teaching all morning in Damascus without it and completely incapable of enjoying the morning.", "modelBand": 7.5, "why": "Takes the question's own word apart first, which is characteristic, then answers it."}, {"q": "Do children in your country start school early?", "ar": null, "topic": "Mornings", "model": "Early enough that nobody has had breakfast properly, which every teacher in Damascus will tell you and nothing is done about. I've taught the first lesson of the day for thirty years, and honestly it isn't the lesson anyone learns anything in.", "modelBand": 7.5, "why": "Thirty years of evidence in two sentences, and a conclusion that is about school rather than about him."}], "voices": {"examiner": "piper-en_GB-alan-medium-s119", "candidate": "piper-en_US-joe-medium-s119"}});
